package com.nexus.access.backend.auth;
import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*; import javax.crypto.SecretKey; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import com.nexus.access.backend.user.User;
@Service public class JwtService { private final SecretKey key; private final long accessExpiration; public JwtService(@Value("${jwt.secret}") String secret,@Value("${jwt.access-expiration}") long accessExpiration){if(secret.length()<32)throw new IllegalStateException("JWT_SECRET must be at least 32 characters");this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.accessExpiration=accessExpiration;} public String create(User user){Instant now=Instant.now();return Jwts.builder().subject(user.getId().toString()).claim("email",user.getEmail()).claim("roles",List.of(user.getRole())).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(accessExpiration))).id(UUID.randomUUID().toString()).signWith(key).compact();} public Claims parse(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();} public long expiration(){return accessExpiration;} }
